#!/usr/bin/env python3
"""Frozen published-clock longitudinal analysis; paired donor bootstrap with LODO refit."""
from pathlib import Path
import sys,json,datetime
import numpy as np,pandas as pd
P=Path(__file__).resolve().parents[2];O=P/'outputs/round6';W=P/'work/round6';sys.path.insert(0,str(P/'outputs/round2_A1'));from run_G1_prime import rng_for,native_indices
from compute_reliability import lodo,batched_lodo,icc_sem,pair_array
CTS=['B','CD4T','CD8T','MONO','NK'];SEED=20261025
def bootstrap_statistics(g,values,pairs,draws,donors):
 idx={s:i for i,s in enumerate(g.gsm)};q=pairs[pairs.gsm1.isin(idx)&pairs.gsm2.isin(idx)];a=np.stack([values[:,[idx[s] for s in q.gsm1]],values[:,[idx[s] for s in q.gsm2]]],axis=2);w=draws[:,[donors.index(d) for d in q.donor]];n=w.sum(axis=1);rm=a.mean(axis=2);cm=(w[:,:,None]*a).sum(axis=1)/n[:,None];gm=cm.mean(axis=1);msr=2*(w*(rm-gm[:,None])**2).sum(axis=1)/(n-1);msc=n*((cm-gm[:,None])**2).sum(axis=1);mse=(w[:,:,None]*(a-rm[:,:,None]-cm[:,None,:]+gm[:,None,None])**2).sum(axis=(1,2))/(n-1);den=msr+mse+2/n*(msc-mse);icc=np.divide(msr-mse,den,out=np.full(len(n),np.nan),where=(n>=3)&(den>0));sd=np.sqrt((w[:,:,None]*(a-gm[:,None,None])**2).sum(axis=(1,2))/(2*n-1));sem=sd*np.sqrt(1-icc);return np.c_[icc,sem,1.96*np.sqrt(2)*sem]
def main():
 assert (O/'all_predictions_complete.json').exists();obs=pd.read_parquet(W/'primary_selected_cells.parquet');rows=[]
 for ct in CTS:
  z=pd.read_csv(W/f'published_{ct}_per_cell_scores.csv.gz');g=obs[obs.celltype.eq(ct)].merge(z,on='barcode',validate='one_to_one');assert len(g)==len(z) and g.score.notna().all()
  for (donor,gsm),x in g.groupby(['donor','gsm']):
   x=x.sort_values('barcode');scores=x.score.to_numpy();n=len(x);ix=native_indices(n,rng_for('R6_Terekhova_published',donor,gsm,ct));pred=float(scores[ix].mean());rows.append({'donor':donor,'gsm':gsm,'celltype':ct,'age':float(x.age.iloc[0]),'prediction':pred,'n_cells':n,'n_technical_libraries':x.File_name.nunique(),'clock':'published_sc-ImmuAging','pseudocells':100,'pseudocell_size':15,'summary':'continuousmean,unrounded','batch':'|'.join(sorted(set(x.Batch)))})
 pred=pd.DataFrame(rows);pred.to_csv(O/'published_donor_visit_predictions.csv',index=False);pairs=pd.read_csv(O/'external_primary_pair_ledger.csv');ids=sorted(pairs.donor.unique());assert pairs.donor.tolist()==ids;draws=np.random.default_rng(np.random.SeedSequence([SEED,6201])).multinomial(len(ids),np.full(len(ids),1/len(ids)),size=2000);np.save(W/'donor_bootstrap_multiplicities.npy',draws);result=[];residual=[];samples={};numerical=[]
 for ct,g in pred.groupby('celltype'):
  g=g.sort_values(['donor','gsm']).reset_index(drop=True);assert sorted(g.donor.unique())==ids;raw=g.prediction.to_numpy();acc=lodo(g,raw);ba=batched_lodo(g,raw,draws);g['age_acceleration']=acc;residual.append(g)
  for metric,values,bv in [('prediction',raw,np.broadcast_to(raw,(2000,len(raw)))),('age_acceleration',acc,ba)]:
   q,a=pair_array(g,values,pairs);point=icc_sem(a);boot=bootstrap_statistics(g,bv,pairs,draws,ids);assert len(q)==len(ids) and np.isfinite(boot).all();
   for ib in range(3):
    _,arr=pair_array(g,bv[ib],pairs);expanded=np.repeat(arr,draws[ib],axis=0);reference=icc_sem(expanded);assert np.allclose(reference,boot[ib],rtol=0,atol=1e-10);numerical.append({'celltype':ct,'metric':metric,'replicate':ib,'max_abs_difference':float(abs(reference-boot[ib]).max())})
   lo,hi=np.percentile(boot,[2.5,97.5],axis=0);result.append({'celltype':ct,'metric':metric,'n_donors':len(q),'n_visits_calibration':len(g),'ICC2_1':point[0],'ICC_CI_low':lo[0],'ICC_CI_high':hi[0],'SEM':point[1],'SEM_CI_low':lo[1],'SEM_CI_high':hi[1],'MDC95':point[2],'MDC95_CI_low':lo[2],'MDC95_CI_high':hi[2],'bootstrap_replicates':2000,'bootstrap_valid':int(np.isfinite(boot).all(axis=1).sum()),'interval':'nominalannualearliest-latest;actualdaysnotretrieved'});samples[ct+'__'+metric]=boot
  print('RELIABILITY_DONE',ct,flush=True)
 (O/'replication_numerical_QA.json').write_text(json.dumps({'status':'PASS','reference':'A1 icc_sem on explicitlyexpanded donorbootstraprows','checks':numerical},indent=2));r=pd.DataFrame(result);r.to_csv(O/'replication_reliability_results.csv',index=False);pd.concat(residual).to_csv(O/'published_predictions_with_LODO.csv',index=False);np.savez_compressed(O/'donor_bootstrap_reliability_distributions.npz',**samples);aida=pd.read_csv(P/'outputs/round5/P4_external_technical_ICC.csv');aida=aida[aida.clock.eq('published')&aida.metric.eq('age_acceleration')].set_index('celltype');cmp=r[r.metric.eq('age_acceleration')].copy();cmp['AIDA_technical_ICC_published']=cmp.celltype.map(aida.ICC2_1);cmp['strictly_below_AIDA_technical']=cmp.ICC2_1.lt(cmp.AIDA_technical_ICC_published);cmp['B_MONO_point_le0_60']=cmp.apply(lambda x:x.ICC2_1<=.60 if x.celltype in ['B','MONO'] else None,axis=1);cmp.to_csv(O/'replication_comparison_with_AIDA.csv',index=False);cr=cmp.set_index('celltype');leg1=bool(cr.loc['B','ICC2_1']<=.60 and cr.loc['MONO','ICC2_1']<=.60);leg2=int(cmp.strictly_below_AIDA_technical.sum())>=3;verdict='复现' if leg1 and leg2 else '未复现';d={'status':'COMPLETE_VALID_ANALYSIS','replication_verdict':verdict,'seed':SEED,'n_donors':len(ids),'B_age_acceleration_ICC':float(cr.loc['B','ICC2_1']),'MONO_age_acceleration_ICC':float(cr.loc['MONO','ICC2_1']),'B_and_MONO_both_le0_60':leg1,'n_types_below_AIDA_published_technical':int(cmp.strictly_below_AIDA_technical.sum()),'at_least3_types_below_AIDA':leg2,'types_below_AIDA':cmp.loc[cmp.strictly_below_AIDA_technical,'celltype'].tolist(),'threshold_unchanged':True,'native_missing_gene_policy':'source-specificmappedfeatures;residualzero asreported,not assumedabsentbiology','time_scope':'nominal1/2yearwaves;actualdatesnotinretrievedcellmetadata','no_variants_e_c_or_training':True,'preregistration_P2_CD4_label':'待声明','recorded_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat()};(O/'replication_decision.json').write_text(json.dumps(d,ensure_ascii=False,indent=2));f=P/'outputs/gate_ledger.json';led=json.loads(f.read_text());led['round6']['replication_decision']=d;f.write_text(json.dumps(led,ensure_ascii=False,indent=2));print(json.dumps(d,ensure_ascii=False,indent=2),flush=True)
if __name__=='__main__':main()
